      'Diseño de líneas estructuradas\n\nEsta icónica colección se define por sus proporciones anchas y líneas estructuradas, creando una pieza que transmite estabilidad y serenidad en cualquier ambiente. Las patas de efecto invisible otorgan al sofá una sensación de ligereza visual, elevando su presencia y realzando la estética contemporánea de tu salón con un diseño único y atemporal.\n\nConfort equilibrado\n\nSu asiento con sentada media-firme combina base de espuma suave de 30kg/m³, una capa de espuma dura de 20kg/m³ y una capa superior de espuma suave de 20kg/m³, logrando el equilibrio perfecto entre comodidad y soporte, ideal tanto para el descanso diario como para recibir a tus invitados. El respaldo, diseñado para ofrecer un extra de confort gracias a su núcleo de espuma dura de 20kg/m³ recubierto de espuma suave de 20kg/m³, invita a recostarse y relajarse. Para una experiencia aún más confortable, recomendamos complementarlo con los cojines de la colección, disponibles por separado.',
